pub mod heuristic;
pub mod llm;
pub mod mock;
pub mod prompt;

use serde::{Deserialize, Serialize};
use crate::diff::DiffSummary;
use crate::error::ReddiffError;

pub use heuristic::HeuristicSynthesizer;
pub use llm::LlmSynthesizer;
pub use mock::MockSynthesizer;

/// A candidate test script generated by a synthesizer.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CandidateTest {
    /// Identifier or rule name (internal, never output to stdout in zero-prose mode)
    pub name: String,
    /// The verbatim runnable test script content
    pub script: String,
    /// Target file extension: "py", "js", "rs", "sh"
    pub file_extension: String,
    /// Explicit runner command (e.g. "python", "node", "cargo test"), or None to infer
    pub runner: Option<String>,
    /// Optional timeout override for this test
    pub timeout_secs: Option<u64>,
}

/// Core abstraction for synthesizing adversarial test candidates.
pub trait Synthesizer: Send + Sync {
    fn synthesize(&self, diff: &DiffSummary) -> Result<Vec<CandidateTest>, ReddiffError>;
}
